// Static tables generated by build.rs, plus the two lookups that read them: whole-token lookup by bytes and
// merge lookup by token pair.

use crate::table_hash::*;

/// Forces 64-byte alignment on embedded table images so they can be viewed as u32/u64 arrays.
#[repr(C, align(64))]
pub(crate) struct Aligned<T>(pub T);

include!(concat!(env!("OUT_DIR"), "/tables.rs"));

const VOCAB_SLOT_MASK: usize = (1 << VOCAB_TABLE_BITS) - 1;
const PAIR_SLOT_MASK: usize = (1 << PAIR_TABLE_BITS) - 1;
const PAIR_RANK_MASK: u64 = (1 << PAIR_ID_BITS) - 1;
/// Rank (merged token id) meaning "these two parts never merge".
pub(crate) const NO_MERGE: u32 = u32::MAX;

/// Bytes of an ordinary token. `id` must be below `TOKEN_COUNT`.
#[inline]
pub(crate) fn ordinary_token_bytes(id: u32) -> &'static [u8] {
    let id = id as usize;
    &TOKEN_BYTES[TOKEN_OFFSETS[id] as usize..TOKEN_OFFSETS[id + 1] as usize]
}

/// Little-endian value of up to 8 bytes, zero padded. Overlapping loads avoid a variable-length copy.
#[inline(always)]
fn load_le_padded(bytes: &[u8]) -> u64 {
    let len = bytes.len();
    if len >= 8 {
        u64::from_le_bytes(bytes[..8].try_into().unwrap())
    } else if len >= 4 {
        let low = u32::from_le_bytes(bytes[..4].try_into().unwrap()) as u64;
        let high = u32::from_le_bytes(bytes[len - 4..len].try_into().unwrap()) as u64;
        low | high << (8 * (len - 4))
    } else if len > 0 {
        bytes[0] as u64 | (bytes[len / 2] as u64) << (8 * (len / 2)) | (bytes[len - 1] as u64) << (8 * (len - 1))
    } else {
        0
    }
}

/// The ordinary token whose bytes are exactly `bytes`, if any.
#[inline]
pub(crate) fn token_id_for_bytes(bytes: &[u8]) -> Option<u32> {
    let len = bytes.len();
    if len == 0 || len > MAX_TOKEN_BYTES {
        return None;
    }
    let head = load_le_padded(bytes);
    let tail = if len > 8 { load_le_padded(&bytes[8..len.min(INLINE_TOKEN_BYTES)]) as u32 } else { 0 };
    let expected = tail as u64 | (len as u64) << VOCAB_SLOT_LEN_SHIFT;
    let mut slot = vocab_slot_for(head, tail, len);
    loop {
        let (slot_head, slot_info) = (VOCAB_TABLE[2 * slot], VOCAB_TABLE[2 * slot + 1]);
        if slot_info == 0 {
            return None;
        }
        if slot_head == head && slot_info & !VOCAB_SLOT_ID_MASK == expected {
            let id = ((slot_info & VOCAB_SLOT_ID_MASK) >> VOCAB_SLOT_ID_SHIFT) as u32;
            if len <= INLINE_TOKEN_BYTES || ordinary_token_bytes(id) == bytes {
                return Some(id);
            }
        }
        slot = (slot + 1) & VOCAB_SLOT_MASK;
    }
}

/// Rank of merging two adjacent tokens: the merged token's id, or `NO_MERGE`.
#[inline(always)]
pub(crate) fn merge_rank(left: u32, right: u32) -> u32 {
    let key = pair_key(left, right);
    let mut slot = pair_slot_for(key);
    loop {
        let entry = PAIR_TABLE[slot];
        if entry >> PAIR_ID_BITS == key {
            return (entry & PAIR_RANK_MASK) as u32;
        }
        if entry == PAIR_EMPTY_SLOT {
            return NO_MERGE;
        }
        slot = (slot + 1) & PAIR_SLOT_MASK;
    }
}

/// Rank of merging two single-byte tokens.
#[inline(always)]
pub(crate) fn byte_merge_rank(left: u8, right: u8) -> u32 {
    BYTE_PAIR_RANKS[(left as usize) << 8 | right as usize]
}
